1. use core::marker;
2. 
3. #[allow(unused_imports)]
4. use super::pervasive::*;
5. #[allow(unused_imports)]
6. use super::prelude::*;
7. 
8. verus! {
9. 
10. #[verifier::ext_equal]
11. #[verifier::accept_recursive_types(A)]
12. tracked enum SeqInner<A> {
13.     Nil,
14.     Cons { head: Tracked<A>, tail: Tracked<SeqInner<A>> },
15. }
16. 
17. // This indirection is required to show the termination of `Seq::len`
18. //
19. // If we translated this to `Seq` we the decrease clauses wouldn't work,
20. // because we would have had to re-internalize the tail into a `Seq`
21. impl<A> SeqInner<A> {
22.     spec fn len(self) -> nat
23.         decreases self,
24.     {
25.         match self {
26.             SeqInner::Nil => 0,
27.             SeqInner::Cons { tail, .. } => { 1 + tail.len() },
28.         }
29.     }
30. 
